import csv
from pathlib import Path


def load_rows(path):
    rows = []
    with Path(path).open(newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            rows.append(row)
    return rows


def sum_column(rows, column):
    acc = 0.0
    for row in rows:
        value = row.get(column, "").strip()
        if not value:
            continue
        try:
            acc += float(value)
        except ValueError:
            print(f"skipping bad value {value!r}")
    return acc


def average_column(rows, column):
    acc = sum_column(rows, column)
    count = sum(1 for row in rows if row.get(column, "").strip())
    if count == 0:
        return 0.0
    return acc / count


def report(path, columns):
    rows = load_rows(path)
    lines = []
    for column in columns:
        acc = sum_column(rows, column)
        mean = average_column(rows, column)
        lines.append(f"{column}: total={acc:.2f} mean={mean:.2f}")
    return "\n".join(lines)


if __name__ == "__main__":
    print(report("sales.csv", ["amount", "tax", "discount"]))
